CREATE TABLE Classes (Class VARCHAR(3) PRIMARY KEY, ClassTeacher VARCHAR(50) NOT NULL);
CREATE TABLE Pupils (PupilID INT PRIMARY KEY, PupilName VARCHAR(50) NOT NULL, Class VARCHAR(3) REFERENCES Classes(Class));
CREATE TABLE Memberships (PupilID INT REFERENCES Pupils(PupilID), ClubID INT REFERENCES Clubs(ClubID), PRIMARY KEY (PupilID, ClubID));
